//! Read-only bounded process snapshot, not proof of global mount/FD quiescence.
use std::{fs::{self,File},io::{self,Read},os::unix::fs::{FileTypeExt,MetadataExt},path::Path};
fn read_bounded(p:&Path,max:u64)->io::Result<String>{let mut x=Vec::new();File::open(p)?.take(max+1).read_to_end(&mut x)?;if x.len() as u64>max{return Err(io::ErrorKind::InvalidData.into())}String::from_utf8(x).map_err(|_|io::ErrorKind::InvalidData.into())}
fn start(p:&Path)->io::Result<String>{let s=read_bounded(&p.join("stat"),65536)?;let tail=s.rsplit_once(')').ok_or(io::ErrorKind::InvalidData)?.1;tail.split_whitespace().nth(19).map(str::to_owned).ok_or(io::ErrorKind::InvalidData.into())}
fn main()->io::Result<()>{let uidmap=read_bounded(Path::new("/proc/self/uid_map"),1024)?;if uidmap.split_whitespace().collect::<Vec<_>>()!=["0","0","4294967295"]{return Err(io::ErrorKind::PermissionDenied.into())}let mut n=0;let(mut unreadable,mut changed,mut ns_refs,mut mount_refs,mut fd_refs,mut mntid_refs,mut overflow)=(0,0,0,0,0,0,0);let mut dirs=Vec::new();for entry in fs::read_dir("/proc")? {match entry {Ok(e)=>{if e.file_name().to_string_lossy().bytes().all(|b|b.is_ascii_digit()){dirs.push(e);if dirs.len()>4096{return Err(io::ErrorKind::InvalidData.into())}}},Err(_)=>unreadable+=1}}dirs.sort_by_key(|e|e.file_name());
for ent in dirs {n+=1;let p=ent.path();let first=match start(&p){Ok(s)=>s,Err(_)=>{unreadable+=1;continue}};let ns=match fs::read_link(p.join("ns/mnt")){Ok(x)=>x.to_string_lossy().into_owned(),Err(_)=>{unreadable+=1;String::new()}};if ns=="mnt:[4026533650]"{ns_refs+=1}
match read_bounded(&p.join("mountinfo"),2_097_152){Ok(m)=>{for row in m.lines(){let f:Vec<_>=row.split_whitespace().collect();if f.len()<6 {unreadable+=1;break}if f[2]=="252:4090"||(ns=="mnt:[4026533650]"&&f[0]=="432"){mount_refs+=1}}},Err(_)=>unreadable+=1}
match fs::read_dir(p.join("fd")){Ok(fds)=>{for (i,fd) in fds.enumerate(){if i>=4096{overflow+=1;break}let fd=match fd{Ok(f)=>f,Err(_)=>{unreadable+=1;continue}};let path=fd.path();match fs::read_link(&path){Ok(t)=>{if t.to_string_lossy()=="mnt:[4026533650]" {ns_refs+=1}},Err(_)=>unreadable+=1}match fs::metadata(&path){Ok(m)=>{if m.file_type().is_block_device()&&m.rdev()==0xf0fcfa {fd_refs+=1}},Err(_)=>unreadable+=1}let info=p.join("fdinfo").join(fd.file_name());match read_bounded(&info,65536){Ok(t)=>{if t.lines().any(|x|x.trim()=="mnt_id:\t432"){mntid_refs+=1}},Err(_)=>unreadable+=1}}},Err(_)=>unreadable+=1}
if start(&p).ok().as_deref()!=Some(first.as_str()){changed+=1}}
println!("PROCESS_SNAPSHOT count={n} unreadable_or_raced={unreadable} identity_changed={changed} namespace_refs={ns_refs} matching_mount_rows={mount_refs} matching_block_fds={fd_refs} ambiguous_mountid_fds={mntid_refs} overflow={overflow}");println!("LIMITATION point-in-time; mount IDs can be reused, and unreadable entries, detached mounts, kernel references and post-snapshot changes remain unknown");Ok(())}
